-- CraftingConfig (2026-10-03, Claude): recipes for the Crafting Machine in Frostfall Village (MachineService checks and crafts).
-- A recipe costs Snow and/or treasures. Only SPARE treasures are used: the last copy of each treasure always stays in the
-- Treasure Book. The Craft panel builds itself from this list. Enabled = false hides a recipe.
-- Reward kinds:
--   {Kind = "Boost",    Boost = "Snow2" | "Luck2" | "Super", Seconds = 600}
--   {Kind = "Shovel",   Item = "<shovel name from RNGConfig>"}
--   {Kind = "Pet",      Pet = "<pet name from PetConfig>"}
--   {Kind = "Treasure", Treasure = "<treasure id from TreasureConfig>"}
--   {Kind = "Snow",     Amount = 1000}
-- Treasure ids come from TreasureConfig (e.g. FrostButton, SnowflakeCharm, IcicleBell, FrozenWatch, HeartOfWinter).
local C = {}
C.Recipes = {
	-- Real recipes get added here later. This example only appears in isolated tests (BalanceTestMode):
	{Id = "ExampleLuckGlobe", Name = "Lucky Snow Globe", Text = "2x Luck for 15 minutes", Snow = 500,
		Treasures = {FrostButton = 2}, Reward = {Kind = "Boost", Boost = "Luck2", Seconds = 900}, Enabled = false, TestOnly = true},
}
return C

-- BACKGROUND MUSIC: add/remove audio ids here.
return {
	Tracks = {
		"rbxassetid://133912801266740", -- Cozy Study Lights
		"rbxassetid://73365286427603",  -- Abstract Radius inside Narrow Domain
		"rbxassetid://1839817333",      -- Live Peacefully
	},
	Volume = 0.22,       -- normal music volume
	DuckVolume = 0.04,   -- volume during the rare-drop cutscene
	Crossfade = 2,       -- seconds of overlap between tracks
	Shuffle = true,
	StartAfterIntro = true, -- wait for the arrival cinematic to end (or be skipped) before the music starts
}

-- MachineConfig (2026-10-03, Claude): the three lobby machines (MachineService does the work, MachinesClient shows the panels).
local M = {}
-- SHOVEL FORGE (Upgrade Workshop): melt spare copies of a shovel into its rarer version. The rates follow the roll odds
-- (a roll is Giant 1 in 5 and Shiny 1 in 10). Equipped copies are never used and you always keep 1 copy (your Index).
M.Forge = {
	{From = nil,     To = "Giant",       Need = 5},
	{From = nil,     To = "Shiny",       Need = 10},
	{From = "Giant", To = "Shiny Giant", Need = 10},
	{From = "Shiny", To = "Shiny Giant", Need = 5},
}
-- HOT COCOA MACHINE (Supply Hut): timed boosts bought with Snow. Price = Snow worth PriceMinutes of your recent digging,
-- so it is fair at every stage (MinSnowPerMinute is the floor for brand-new players). Boost time stacks (max 1 hour).
M.Cocoa = {
	MinSnowPerMinute = 50,
	Drinks = {
		{Id = "Snowy", Name = "Snowy Cocoa", Boost = "Snow2", Seconds = 600, PriceMinutes = 6, Color = Color3.fromRGB(110, 200, 255), Icon = "snow"},
		{Id = "Lucky", Name = "Lucky Cocoa", Boost = "Luck2", Seconds = 600, PriceMinutes = 5, Color = Color3.fromRGB(105, 220, 125), Icon = "luck"},
		{Id = "Super", Name = "Super Cocoa", Boost = "Super", Seconds = 300, PriceMinutes = 6, Color = Color3.fromRGB(255, 195, 70),  Icon = "rewards"},
	},
}
-- PET FUSER (Pet Lodge): Need spare copies of the same pet -> 1 Golden version (PetConfig.GoldenMult x boost). Equipped pets are
-- never used.
M.Fuser = {Need = 3}
return M
